styleCss:
.kp-logo { height: 70px; margin-left: 20px; }
.kp-logo-wrapper { float: left; }
.research-portal-header { height: 90px; background-color: #ffffff; border-bottom: solid 1px #dddddd }
.research-portal-header  ul { float: right; font-size: 16px; margin-top: 25px; padding-right: 40px; }
.research-header-menu-wrapper ul li.menu a { color: #333333 !important; font-size: 18px !important;}
.research-header-menu-wrapper ul li.menu a:hover { color: #000000 !important; }
.paper-footer-wrapper { background-color: #4480b2; }

.mdkp-body {
    background-color: #ffffff;
    width: 1024px;
    margin: auto;
    font-size: 1.35em;
}

.card {
    border: none !important;
}

body.kp-default {
    background-color: #ffffff;
    font-family: arial, sans-serif;
}

.dataset-page-header .col-md-8 {
    display: block !important;
    margin: auto;
    width: 100% !important;
    text-align: center;
}

.dataset-page-header h3 {
    font-size: 3.5rem;
}

.kp-tabs-contents {
    display: none;
}
